-- ============================================================================================
-- CVM_CLIENT_ITEM_T3_ROLLBACK_20261101 — откат правки Т3 бэклога ночного задания (CVM_CLIENT_ITEM_T3_20261101.sql):
--   dbo.client_item_load — текст в базе с 19.10.2026; dbo.client_item_keys_day — текст CVM_CLIENT_ITEM_CATVER_20261023.sql
--   (как в базе до Т3, но с правильной кириллицей — работает так же). Выполняется заданием CVM_API_nightly из обменника.
-- Те же проверки, что у применения: тексты сейчас — версии Т3 (иначе стоп), 05:30–09:00 по серверу и задание не ближе трёх
-- шагов к CLIENT_ITEM, замок витрины
-- CVM_CLIENT_ITEM; тексты Т3 перед откатом — в dbo.I_DISCOUNT_PROC_BACKUP; ALTER обеих одной транзакцией со сверкой хэша.
-- Сообщения раннеру — латиницей.
-- ============================================================================================

USE mci_model
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_WARNINGS ON;
SET ANSI_PADDING ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET ARITHABORT ON;
SET NUMERIC_ROUNDABORT OFF;
GO
DECLARE @from_load varbinary(32) = 0x75B0D344590E54CD99874D2322BC18DCDA4BEAC4D9BEBAF64EFC3F3A5BD3FBDF   -- client_item_load после правки Т3
      , @from_keys varbinary(32) = 0x699042EF2A615CF875604BC7D6EDEC6923A214B01BFA07CDED36932A275DB594   -- client_item_keys_day после правки Т3
      , @from_keys_alt varbinary(32) = 0x699042EF2A615CF875604BC7D6EDEC6923A214B01BFA07CDED36932A275DB594   -- client_item_keys_day после правки Т3
      , @to_load   varbinary(32) = 0x31C1B4A84A2A9BAE3A4164E14EE5F16A97EC2BCE5D14765EA69DC47378F62986   -- client_item_load до Т3 (keys_day — с восстановленной кириллицей)
      , @to_keys   varbinary(32) = 0x8A993B83175FE477F0F0447770EA452C2A99B76985D3A9F39046FA582BA152E7   -- client_item_keys_day до Т3 (keys_day — с восстановленной кириллицей)
      , @hl nvarchar(60) = N'CREATE   PROCEDURE dbo.client_item_load'
      , @hk nvarchar(60) = N'CREATE   PROCEDURE dbo.client_item_keys_day'
      , @def_load nvarchar(max), @def_keys nvarchar(max), @new_load nvarchar(max), @new_keys nvarchar(max), @x nvarchar(max)
      , @vl varbinary(max), @vk varbinary(max), @lk int, @msg nvarchar(2048), @step varchar(30) = 'check';

-- ============================== 0. ПРОВЕРКИ ==============================
-- Раннер вызывает sqlcmd с -b: RAISERROR 16 обрывает скрипт, он остаётся в обменнике и повторяется через 10 минут;
-- PRINT + RETURN («уже сделано») — успех, раннер уносит файл в done.
SET @def_load = OBJECT_DEFINITION(OBJECT_ID(N'dbo.client_item_load'));
SET @def_keys = OBJECT_DEFINITION(OBJECT_ID(N'dbo.client_item_keys_day'));
IF @def_load IS NULL OR @def_keys IS NULL
BEGIN
    RAISERROR(N'STOP: client_item_load or client_item_keys_day not found or no rights to text - nothing changed.', 16, 1);
    RETURN;
END
-- CREATE OR ALTER сервер хранит как «CREATE   PROCEDURE» (так стоят обе процедуры сейчас); на всякий случай — обе формы
SET @def_load = REPLACE(@def_load COLLATE Latin1_General_BIN2, N'CREATE OR ALTER PROCEDURE dbo.client_item_load', @hl);
SET @def_keys = REPLACE(@def_keys COLLATE Latin1_General_BIN2, N'CREATE OR ALTER PROCEDURE dbo.client_item_keys_day', @hk);
IF HASHBYTES('SHA2_256', @def_load) = @to_load AND HASHBYTES('SHA2_256', @def_keys) = @to_keys
BEGIN
    PRINT N'T3 ROLLBACK: client_item_load and client_item_keys_day already in target version - nothing to do.';
    RETURN;
END
IF HASHBYTES('SHA2_256', @def_load) <> @from_load
   OR HASHBYTES('SHA2_256', @def_keys) NOT IN (@from_keys, @from_keys_alt)
BEGIN
    RAISERROR(N'STOP: client_item_load / client_item_keys_day text is not the one T3 ROLLBACK was built on (01.11.2026) - nothing changed.', 16, 1);
    RETURN;
END
-- окно: «MCI Regular update» идёт (история витрины в это время ждёт), шаг CLIENT_ITEM ещё далеко: до Т8 он начинался в
-- 10:20–10:30, по порядку А1 — после эффекта; окно кончается в 09:00, и задание не ближе трёх шагов к CLIENT_ITEM
-- (иначе загрузка дней, взяв замок с таймаутом 0, упала бы на нашем замке и ночь бы пропустилась)
IF CAST(GETDATE() AS time) NOT BETWEEN '05:30' AND '09:00'
BEGIN
    RAISERROR(N'Wait: T3 ROLLBACK applies only 05:30-09:00 server time (CLIENT_ITEM step far, history load paused); exchange will retry in 10 min.', 16, 1);
    RETURN;
END
IF EXISTS (SELECT 1
           FROM msdb.dbo.sysjobactivity AS a WITH (NOLOCK)
                JOIN msdb.dbo.sysjobs AS j WITH (NOLOCK) ON j.job_id = a.job_id
           WHERE j.name = N'MCI Regular update'
             AND a.session_id = (SELECT MAX(s.session_id) FROM msdb.dbo.syssessions AS s WITH (NOLOCK))
             AND a.start_execution_date IS NOT NULL AND a.stop_execution_date IS NULL
             AND ISNULL(a.last_executed_step_id, 0) >= ISNULL((SELECT MIN(js.step_id) FROM msdb.dbo.sysjobsteps AS js WITH (NOLOCK)
                                                               WHERE js.job_id = j.job_id AND js.step_name = N'CLIENT_ITEM'), 0) - 3)
BEGIN
    RAISERROR(N'Wait: MCI Regular update is within 3 steps of CLIENT_ITEM (or the step is missing); exchange will retry in 10 min.', 16, 1);
    RETURN;
END

-- ============================== 1. ТЕКСТЫ (UTF-16LE, байт в байт) ==============================
SET @vk = 0x;
SET @vk = @vk + ;
SET @vk = @vk + ;
SET @vk = @vk + ;
SET @vk = @vk + ;
SET @vk = @vk + ;
SET @vk = @vk + ;
SET @vk = @vk + ;
SET @vl = 0x;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @vl = @vl + ;
SET @new_keys = CAST(@vk AS nvarchar(max));
SET @new_load = CAST(@vl AS nvarchar(max));
IF HASHBYTES('SHA2_256', @new_keys) <> @to_keys OR HASHBYTES('SHA2_256', @new_load) <> @to_load
   OR CHARINDEX(@hk COLLATE Latin1_General_BIN2, @new_keys COLLATE Latin1_General_BIN2) = 0
   OR CHARINDEX(@hl COLLATE Latin1_General_BIN2, @new_load COLLATE Latin1_General_BIN2) = 0
BEGIN
    RAISERROR(N'STOP: T3 ROLLBACK texts damaged in transfer (hash) - nothing changed.', 16, 1);
    RETURN;
END

-- ============================== 2. ПРИМЕНЕНИЕ ПОД ЗАМКОМ ВИТРИНЫ ==============================
-- Замок тот же, что берут загрузка дней (client_item_load) и пересборка ключей: пока он у нас, витрину никто не пишет;
-- занят — ждём следующего прохода. Обе процедуры — одной транзакцией, со сверкой хэша сохранённого текста.
EXEC @lk = sys.sp_getapplock @Resource = N'CVM_CLIENT_ITEM', @LockMode = N'Exclusive', @LockOwner = N'Session', @LockTimeout = 0;
IF @lk < 0
BEGIN
    RAISERROR(N'Wait: CVM_CLIENT_ITEM lock is held (day load, history or key rebuild running); exchange will retry in 10 min.', 16, 1);
    RETURN;
END
BEGIN TRY
    BEGIN TRAN;
        SET @step = 'backup';
        INSERT INTO dbo.I_DISCOUNT_PROC_BACKUP (PROC_NAME, SAVED_AT, DEFINITION)
        VALUES (N'client_item_keys_day', SYSDATETIME(), OBJECT_DEFINITION(OBJECT_ID(N'dbo.client_item_keys_day')))
             , (N'client_item_load', SYSDATETIME(), OBJECT_DEFINITION(OBJECT_ID(N'dbo.client_item_load')));
        SET @step = 'alter keys_day';
        SET @x = STUFF(@new_keys, CHARINDEX(@hk COLLATE Latin1_General_BIN2, @new_keys COLLATE Latin1_General_BIN2),
                       LEN(N'CREATE   PROCEDURE'), N'CREATE OR ALTER PROCEDURE');
        EXEC sys.sp_executesql @x;
        SET @step = 'alter load';
        SET @x = STUFF(@new_load, CHARINDEX(@hl COLLATE Latin1_General_BIN2, @new_load COLLATE Latin1_General_BIN2),
                       LEN(N'CREATE   PROCEDURE'), N'CREATE OR ALTER PROCEDURE');
        EXEC sys.sp_executesql @x;
        SET @step = 'verify';
        IF HASHBYTES('SHA2_256', REPLACE(OBJECT_DEFINITION(OBJECT_ID(N'dbo.client_item_keys_day')) COLLATE Latin1_General_BIN2,
                                         N'CREATE OR ALTER PROCEDURE dbo.client_item_keys_day', @hk)) <> @to_keys
           OR HASHBYTES('SHA2_256', REPLACE(OBJECT_DEFINITION(OBJECT_ID(N'dbo.client_item_load')) COLLATE Latin1_General_BIN2,
                                            N'CREATE OR ALTER PROCEDURE dbo.client_item_load', @hl)) <> @to_load
           OR ISNULL(OBJECTPROPERTY(OBJECT_ID(N'dbo.client_item_keys_day'), 'ExecIsQuotedIdentOn'), 0) <> 1
           OR ISNULL(OBJECTPROPERTY(OBJECT_ID(N'dbo.client_item_load'), 'ExecIsQuotedIdentOn'), 0) <> 1
            THROW 50030, N'T3 ROLLBACK: text after ALTER does not match - rolled back.', 1;
    COMMIT;
    EXEC sys.sp_releaseapplock @Resource = N'CVM_CLIENT_ITEM', @LockOwner = N'Session';
    PRINT N'T3 ROLLBACK APPLIED: client_item_keys_day and client_item_load altered; previous texts in I_DISCOUNT_PROC_BACKUP.';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK;
    IF APPLOCK_MODE(N'public', N'CVM_CLIENT_ITEM', N'Session') <> N'NoLock'
        EXEC sys.sp_releaseapplock @Resource = N'CVM_CLIENT_ITEM', @LockOwner = N'Session';
    SET @msg = LEFT(CONCAT(N'T3 ROLLBACK ERROR at ', @step, N' (nothing changed): ', ERROR_NUMBER(), N' line ', ERROR_LINE(), N': ',
                           ERROR_MESSAGE()), 2040);
    RAISERROR(N'%s', 16, 1, @msg);
END CATCH
GO
